import { describe, it, expect } from "vitest";
import { resolve, dirname } from "path";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import * as zarr from "zarrita";
import type { AsyncReadable } from "../src/types.js";
import { HdfStore, SingleHdf5ToZarr } from "../src/index.js";

const fixturesDir = resolve(dirname(fileURLToPath(import.meta.url)), "fixtures");
const FIXTURE = "vlen_strings.h5";

/** Generated by test/fixtures/vlen_strings.py from h5py reads. */
const expected: {
  values: Record<string, string[]>;
  shapes: Record<string, number[]>;
  many_chunks: {
    chunks: { index: number; offset: number; size: number; collections: number[] }[];
    collections: { offset: number; size: number }[];
  };
} = JSON.parse(readFileSync(resolve(fixturesDir, "vlen_strings.expected.json"), "utf-8"));

/** Datasets whose chunks cannot be decoded in JS (unsupported filters). */
const UNSUPPORTED = new Set(["lzf"]);

/** In-memory source that records every getRange call. */
class SpySource implements AsyncReadable {
  calls: Array<{ offset: number; length: number }> = [];
  readonly data: Uint8Array;

  constructor(fixtureName: string) {
    this.data = new Uint8Array(readFileSync(resolve(fixturesDir, fixtureName)));
  }

  async get(): Promise<Uint8Array> {
    throw new Error("HdfStore should only use getRange");
  }

  async getRange(_key: string, range: { offset: number; length: number } | { suffixLength: number }) {
    if (!("offset" in range)) throw new Error("unexpected suffix read");
    const { offset, length } = range;
    this.calls.push({ offset, length });
    return this.data.slice(offset, offset + length);
  }
}

/** Decode a vlen-utf8 chunk (u32 count, then u32 length + UTF-8 bytes per item). */
function decodeVlenUtf8(bytes: Uint8Array): string[] {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const decoder = new TextDecoder();
  const out: string[] = [];
  let pos = 4;
  for (let i = 0; i < view.getUint32(0, true); i++) {
    const length = view.getUint32(pos, true);
    out.push(decoder.decode(bytes.subarray(pos + 4, pos + 4 + length)));
    pos += 4 + length;
  }
  expect(pos).toBe(bytes.byteLength);
  return out;
}

async function readArray(store: HdfStore, path: string) {
  const arr = await zarr.open(zarr.root(store).resolve(path), { kind: "array" });
  // zarrita cannot `get` zero-size arrays ("Input contains an empty iterator").
  if (arr.shape.includes(0)) return { shape: arr.shape, data: [] };
  const result = await zarr.get(arr);
  // zarrita returns the bare value for 0-d arrays.
  if (arr.shape.length === 0) return { shape: [], data: [result as unknown as string] };
  const chunk = result as { data: string[]; shape: number[] };
  return { shape: chunk.shape, data: Array.from(chunk.data) };
}

async function zarrJson(store: HdfStore, path: string) {
  return JSON.parse(new TextDecoder().decode(await store.get(`/${path}/zarr.json`)));
}

describe("string datasets: values match h5py", () => {
  for (const name of Object.keys(expected.values)) {
    if (UNSUPPORTED.has(name)) continue;
    it(name, async () => {
      const store = await HdfStore.fromStore(new SpySource(FIXTURE));
      const { shape, data } = await readArray(store, name);
      expect(shape).toEqual(expected.shapes[name]);
      expect(data).toEqual(expected.values[name]);
    });
  }

  it("all datasets, through withRangeCoalescing and with a tiny heap cache", async () => {
    const store = await HdfStore.fromStore(zarr.withRangeCoalescing(new SpySource(FIXTURE)), {
      maxGlobalHeapCacheBytes: 1,
    });
    for (const name of Object.keys(expected.values)) {
      if (UNSUPPORTED.has(name)) continue;
      expect((await readArray(store, name)).data).toEqual(expected.values[name]);
    }
  });
});

describe("string datasets: v3 metadata", () => {
  it("chunked: regular grid of HDF5 chunks, vlen-utf8 codec", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    const meta = await zarrJson(store, "chunked_gzip");
    expect(meta).toMatchObject({
      zarr_format: 3,
      node_type: "array",
      shape: [1003],
      data_type: "string",
      fill_value: "",
      codecs: [{ name: "vlen-utf8" }],
      chunk_grid: { name: "regular", configuration: { chunk_shape: [64] } },
      chunk_key_encoding: { name: "default", configuration: { separator: "/" } },
    });
    expect((await zarrJson(store, "chunked_2d")).chunk_grid.configuration.chunk_shape).toEqual([4, 3]);
  });

  it("contiguous / compact / scalar: virtual chunks of at most 65,536 elements", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    expect((await zarrJson(store, "contiguous_large")).chunk_grid.configuration.chunk_shape).toEqual([65536]);
    expect((await zarrJson(store, "contiguous_2d")).chunk_grid.configuration.chunk_shape).toEqual([5, 4]);
    expect((await zarrJson(store, "compact")).chunk_grid.configuration.chunk_shape).toEqual([4]);
    expect((await zarrJson(store, "scalar")).chunk_grid.configuration.chunk_shape).toEqual([]);
    expect((await zarrJson(store, "fixed_contiguous")).data_type).toBe("string");
  });

  it("getConsolidatedMetadata reports the same chunk grids", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    const { metadata } = (await store.getConsolidatedMetadata()).consolidated_metadata;
    for (const name of ["chunked_gzip", "contiguous_large", "scalar", "fixed_chunked", "lzf"]) {
      expect(metadata[name]).toEqual(await zarrJson(store, name));
    }
    expect((metadata.many_chunks.chunk_grid as any).configuration.chunk_shape).toEqual([500]);
  });
});

describe("string datasets: chunk encoding", () => {
  it("edge chunks are padded with empty strings to the full chunk shape", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    // chunked: 1003 = 15 * 64 + 43
    const last = decodeVlenUtf8((await store.get("/chunked_gzip/c/15"))!);
    expect(last).toHaveLength(64);
    expect(last.slice(0, 43)).toEqual(expected.values.chunked_gzip.slice(960));
    expect(last.slice(43)).toEqual(new Array(21).fill(""));
    // contiguous: 70001 = 65536 + 4465
    const virtual = decodeVlenUtf8((await store.get("/contiguous_large/c/1"))!);
    expect(virtual).toHaveLength(65536);
    expect(virtual.slice(0, 4465)).toEqual(expected.values.contiguous_large.slice(65536));
    expect(virtual[4465]).toBe("");
    // 2-D edge chunk (rows 8..11 x cols 9..11 of a 9 x 11 array)
    const corner = decodeVlenUtf8((await store.get("/chunked_2d/c/2/3"))!);
    expect(corner).toEqual([expected.values.chunked_2d[8 * 11 + 9], expected.values.chunked_2d[8 * 11 + 10], "", "", "", "", "", "", "", "", "", ""]);
  });

  it("returns undefined for unwritten chunks and keys outside the grid", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    expect(await store.get("/chunked_sparse/c/0")).toBeUndefined();
    expect(await store.get("/chunked_sparse/c/3")).toBeInstanceOf(Uint8Array);
    expect(await store.get("/chunked_gzip/c/16")).toBeUndefined();
    expect(await store.get("/chunked_gzip/c/0/0")).toBeUndefined();
    expect(await store.get("/contiguous_large/c/2")).toBeUndefined();
    expect(await store.get("/empty/c/0")).toBeUndefined();
    expect(decodeVlenUtf8((await store.get("/scalar/c"))!)).toEqual(["scalar é value"]);
  });

  it("errors clearly on unsupported filters", async () => {
    const store = await HdfStore.fromStore(new SpySource(FIXTURE));
    await expect(store.get("/lzf/c/0")).rejects.toThrow(/lzf.*Unsupported HDF5 filter id 32000/);
  });
});

describe("string datasets: partial reads", () => {
  const overlaps = (a: { offset: number; length: number }, start: number, size: number) =>
    a.offset < start + size && start < a.offset + a.length;

  it("reading one chunk touches only that chunk and the heap collections it references", async () => {
    const source = new SpySource(FIXTURE);
    const store = await HdfStore.fromStore(source);
    await zarr.open(zarr.root(store).resolve("many_chunks"), { kind: "array" });
    source.calls = [];

    const target = expected.many_chunks.chunks.find((c) => c.index === 3)!;
    const strings = decodeVlenUtf8((await store.get("/many_chunks/c/3"))!);
    expect(strings).toEqual(expected.values.many_chunks.slice(1500, 2000));

    const referenced = new Set(target.collections);
    // Every byte range read is either the target chunk, a referenced collection, or neither data
    // (e.g. B-tree nodes): no other chunk and no unreferenced collection is touched.
    for (const call of source.calls) {
      for (const chunk of expected.many_chunks.chunks) {
        if (chunk.index !== 3) expect(overlaps(call, chunk.offset, chunk.size)).toBe(false);
      }
      for (const collection of expected.many_chunks.collections) {
        if (!referenced.has(collection.offset)) {
          expect(overlaps(call, collection.offset, collection.size)).toBe(false);
        }
      }
    }
    expect(source.calls.some((c) => overlaps(c, target.offset, target.size))).toBe(true);
    for (const offset of referenced) {
      expect(source.calls.some((c) => overlaps(c, offset, 1))).toBe(true);
    }
    const allowed =
      target.size +
      expected.many_chunks.collections.filter((c) => referenced.has(c.offset)).reduce((a, c) => a + c.size, 0);
    const read = source.calls.reduce((a, c) => a + c.length, 0);
    // Allow a few KiB for the chunk B-tree.
    expect(read).toBeLessThan(allowed + 8192);
  });

  it("heap collections shared by neighbouring chunks are fetched once", async () => {
    const source = new SpySource(FIXTURE);
    const store = await HdfStore.fromStore(source);
    await store.get("/many_chunks/c/3");
    source.calls = [];
    await store.get("/many_chunks/c/3");
    // Only the chunk itself is read again: the chunk index and collection are cached.
    expect(source.calls).toHaveLength(1);
  });

  it("metadata reads do not touch string data", async () => {
    const source = new SpySource(FIXTURE);
    const store = await HdfStore.fromStore(source);
    await store.getConsolidatedMetadata();
    for (const call of source.calls) {
      for (const chunk of expected.many_chunks.chunks) {
        expect(overlaps(call, chunk.offset, chunk.size)).toBe(false);
      }
      for (const collection of expected.many_chunks.collections) {
        expect(overlaps(call, collection.offset, collection.size)).toBe(false);
      }
    }
  });
});

describe("reference-spec output keeps json2 inlining", () => {
  it("chunked vlen strings are a single json2 chunk", async () => {
    const converter = new SingleHdf5ToZarr(new SpySource(FIXTURE), { url: null });
    const { refs } = await converter.translate();
    expect(JSON.parse(refs["chunked_gzip/.zarray"] as string).filters[0].id).toBe("json2");
    const json2 = JSON.parse(refs["chunked_gzip/0"] as string);
    expect(json2.slice(0, -2)).toEqual(expected.values.chunked_gzip);
  });
});
